class Account:
    def __init__(self, purchases, total_cents, total_this_month_cents):
        self.purchases = purchases
        self.total_cents = total_cents
        self.total_this_month_cents = total_this_month_cents

from io_shop.accounts import Account
from io_shop.spend_summary import average_spend_per_item_this_month


class Purchase:
    def __init__(self, amount_cents, in_current_month):
        self.amount_cents = amount_cents
        self.in_current_month = in_current_month


def test_the_monthly_average_is_correct_for_a_shopper_who_did_buy():
    account = Account(
        purchases=[Purchase(500, True), Purchase(300, True)],
        total_cents=800,
        total_this_month_cents=800,
    )

    assert average_spend_per_item_this_month(account) == 400


def test_no_purchases_this_month_returns_zero_instead_of_dividing_by_zero():
    account = Account(purchases=[], total_cents=0, total_this_month_cents=0)

    assert average_spend_per_item_this_month(account) == 0


def test_only_older_purchases_returns_zero_instead_of_dividing_by_zero():
    account = Account(
        purchases=[Purchase(1200, False), Purchase(400, False)],
        total_cents=1600,
        total_this_month_cents=0,
    )

    assert average_spend_per_item_this_month(account) == 0


def test_missing_purchase_list_is_tolerated():
    account = Account(purchases=None, total_cents=0, total_this_month_cents=0)

    assert average_spend_per_item_this_month(account) == 0


def test_account_exposes_the_totals_it_was_constructed_with():
    account = Account(purchases=[], total_cents=900, total_this_month_cents=250)

    assert account.total_cents == 900
    assert account.total_this_month_cents == 250
